select t.machine_id,t.machine_id machineId,t.charge_id,t.charge_id chargeId,t.charge_degrees,t.charge_degrees
chargeDegrees,t.remark,t.status_cd,t.status_cd statusCd,t.charge_money,t.charge_money
chargeMoney,t.state,t.community_id,t.community_id communityId
from meter_machine_charge t
where 1 =1

    and t.machine_id= #{machineId}


    and t.charge_id= #{chargeId}


    and t.charge_degrees= #{chargeDegrees}


    and t.remark= #{remark}


    and t.status_cd= #{statusCd}


    and t.charge_money= #{chargeMoney}


    and t.state= #{state}


    and t.community_id= #{communityId}

order by t.create_time desc

    limit #{page}, #{row}

